CREATE TABLE o1(w, x, y, z UNIQUE, PRIMARY KEY(w, x)); CREATE INDEX o1y ON t1(y); INSERT INTO o1 VALUES(0, 0, 'i', 'one'); INSERT INTO o1 VALUES(0, 1, 'ii', 'two'); INSERT INTO o1 VALUES(1, 0, 'iii', 'three'); INSERT INTO o1 VALUES(1, 1, 'iv', 'four'); CREATE TRIGGER tro1 BEFORE UPDATE ON o1 BEGIN INSERT INTO log VALUES(old.z || '->' || new.z); END; CREATE TRIGGER tro2 AFTER UPDATE ON o1 BEGIN INSERT INTO log VALUES(old.y || '->' || new.y); END;